WITH FilteredCustomers AS (SELECT *, CASE WHEN country = 'DE' THEN 1 ELSE 0 END AS is_de FROM customers WHERE age BETWEEN 47 AND 64 AND country != 'DE'), Agg AS (SELECT CASE WHEN age >= 69 THEN 'high' WHEN age >= 33 THEN 'mid' ELSE 'low' END AS age_bucket, COUNT(DISTINCT is_de) AS unique_citys FROM FilteredCustomers GROUP BY CASE WHEN age >= 69 THEN 'high' WHEN age >= 33 THEN 'mid' ELSE 'low' END) SELECT * FROM Agg ORDER BY unique_citys DESC, age_bucket LIMIT 5;
